import requests
import sys
import json
from typing import Dict, Any

def check_endpoint(url: str, timeout: int = 10) -> Dict[str, Any]:
    """Check the health of a single endpoint"""
    result = {
        "url": url,
        "status": "unknown",
        "status_code": None,
        "response_time_ms": None,
        "error": None,
        "response_text": None
    }

    try:
        response = requests.get(url, timeout=timeout, verify=False)
        result["status_code"] = response.status_code
        result["response_time_ms"] = response.elapsed.total_seconds() * 1000

        # Try to parse response as JSON or text
        try:
            result["response_text"] = response.json()
        except:
            result["response_text"] = response.text

        if 200 <= response.status_code < 300:
            result["status"] = "healthy"
        elif 300 <= response.status_code < 400:
            result["status"] = "redirect"
        elif 400 <= response.status_code < 500:
            result["status"] = "client_error"
        elif 500 <= response.status_code < 600:
            result["status"] = "server_error"
        else:
            result["status"] = "unknown_status"

    except requests.exceptions.Timeout:
        result["status"] = "timeout"
        result["error"] = f"Request timed out after {timeout}s"
    except requests.exceptions.ConnectionError as e:
        result["status"] = "connection_error"
        result["error"] = str(e)
    except requests.exceptions.RequestException as e:
        result["status"] = "request_error"
        result["error"] = str(e)
    except Exception as e:
        result["status"] = "unknown_error"
        result["error"] = str(e)

    return result

def main():
    endpoints = [
        "http://localhost:47301/checkConnectivity?variant=2",
        "https://httpstat.us/200"
    ]

    print("Health Check Results:")
    print("=" * 80)

    all_healthy = True
    issues = []

    for url in endpoints:
        print(f"\nChecking: {url}")
        result = check_endpoint(url)

        if result["status"] == "healthy":
            print(f"  ✓ Status: {result['status']}")
            print(f"  Status Code: {result['status_code']}")
            print(f"  Response Time: {result['response_time_ms']:.2f} ms")

            # Check response content for potential issues
            if result["response_text"]:
                if isinstance(result["response_text"], dict):
                    # Look for warning indicators in JSON response
                    if "status" in result["response_text"] and result["response_text"]["status"].lower() in ["warning", "error", "degraded"]:
                        issue_msg = f"Endpoint {url} returned warning in response: {result['response_text']}"
                        issues.append(issue_msg)
                        print(f"  ⚠ Warning: Response contains potential issue")
                elif isinstance(result["response_text"], str):
                    # Look for warning indicators in text response
                    warning_indicators = ["warning", "error", "degraded", "unavailable", "down"]
                    if any(indicator in result["response_text"].lower() for indicator in warning_indicators):
                        issue_msg = f"Endpoint {url} returned warning text: {result['response_text'][:100]}..."
                        issues.append(issue_msg)
                        print(f"  ⚠ Warning: Response contains potential issue")
        else:
            all_healthy = False
            issue_msg = f"Endpoint {url} is not healthy. Status: {result['status']}"
            if result["error"]:
                issue_msg += f", Error: {result['error']}"
            issues.append(issue_msg)

            print(f"  ✗ Status: {result['status']}")
            if result["status_code"]:
                print(f"  Status Code: {result['status_code']}")
            if result["error"]:
                print(f"  Error: {result['error']}")

    print("\n" + "=" * 80)
    print("\nSummary:")
    print("-" * 80)

    if all_healthy and not issues:
        print("✅ All endpoints are healthy and responding normally.")
    else:
        print("⚠ Issues detected:")
        for issue in issues:
            print(f"  • {issue}")

        if not all_healthy:
            print(f"\n❌ Some endpoints are not healthy. Please investigate.")
        elif issues:
            print(f"\n⚠ Some endpoints returned warnings in their responses. Service may be degraded.")

if __name__ == "__main__":
    # Disable SSL warnings for testing
    import urllib3
    urllib3.disable_warnings(urllib3.exceptions.InsecureRequestWarning)

    main()

